//! Unicode 17.0.0 data, generated by data/generate.py using the pinned UCD.
const UNICODE: &[u8] = include_bytes!("data/case-fold.bin");
const LEGACY: &[u8] = include_bytes!("data/legacy-case.bin");
const ID_START: &[u8] = include_bytes!("data/id-start.bin");
const ID_CONTINUE: &[u8] = include_bytes!("data/id-continue.bin");

fn u16_at(data: &[u8], at: usize) -> usize {
    u16::from_le_bytes(data[at..at + 2].try_into().unwrap()) as usize
}

fn u32_at(data: &[u8], at: usize) -> u32 {
    u32::from_le_bytes(data[at..at + 4].try_into().unwrap())
}

fn group(point: u32, unicode: bool) -> &'static [u8] {
    let data = if unicode { UNICODE } else { LEGACY };
    let count = u32_at(data, 0) as usize;
    let records = &data[4..4 + count * 8];
    let mut lo = 0;
    let mut hi = count;
    while lo < hi {
        let mid = (lo + hi) / 2;
        let index = mid * 8;
        match u32_at(records, index).cmp(&point) {
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
            std::cmp::Ordering::Equal => {
                let at = 4 + records.len() + u16_at(records, index + 4) * 4;
                let size = u16_at(records, index + 6) * 4;
                return &data[at..at + size];
            }
        }
    }
    &[]
}

pub(super) fn equivalents(point: u32, unicode: bool) -> impl Iterator<Item = u32> {
    group(point, unicode)
        .as_chunks::<4>()
        .0
        .iter()
        .copied()
        .map(u32::from_le_bytes)
}

fn contains(data: &[u8], point: u32) -> bool {
    let mut lo = 0;
    let mut hi = data.len() / 8;
    while lo < hi {
        let mid = (lo + hi) / 2;
        let at = mid * 8;
        if point < u32_at(data, at) {
            hi = mid;
        } else if point > u32_at(data, at + 4) {
            lo = mid + 1;
        } else {
            return true;
        }
    }
    false
}

pub(crate) fn identifier_start(point: u32) -> bool {
    contains(ID_START, point)
}

pub(crate) fn identifier_continue(point: u32) -> bool {
    contains(ID_CONTINUE, point)
}
